sys_variable_value.value:
(function execute(inputs, outputs) {
 
var dateParts = inputs.deactivateDate.split('/'); // Divide a string em partes [dia, mês, ano]
var formattedDate = dateParts[2] + '-' + dateParts[1] + '-' + dateParts[0];

var myObj = {
  "CompanyCode": inputs.companyCode,
  "BusinessEntity": inputs.businessEntity,
  "Luc": inputs.luc,
  "DeactivatedDate": formattedDate
};

   gs.info('***Integra+ '+ JSON.stringify(myObj));
    outputs.payloadbasic = myObj;
 
})(inputs, outputs);

